 shadow += SampleShadowAtlas(
 TEXTURE2D_SHADOW_ARGS(shadowAtlas, shadowSampler),
 float3(positionSTS.xy + offset, positionSTS.z)
 );
 }
 return shadow / POISSON_SAMPLE_COUNT;
}

