using UnityEditor;
using UnityEngine;

namespace ArcToon.Editor.ShaderEditor
{
 /// <summary>
 /// ShaderGUI-specific layout utilities.
 /// Shared visual styling is delegated to <see cref="EditorGUILayoutUtils"/>.
 /// </summary>
 public static class ShaderGUILayout
 {
 public static int GUIComponentSpace => EditorGUILayoutUtils.GUIComponentSpace;

 public static int GUIComponentIndentLevel => EditorGUILayoutUtils.GUIComponentIndentLevel;

 public static GUIStyle GUIComponentBoxStyle => EditorGUILayoutUtils.GUIComponentBoxStyle;

 public static GUIStyle GUIFoldoutGroupBoxStyle => EditorGUILayoutUtils.GUIFoldoutGroupBoxStyle;

 public static bool DrawGUIComponentFoldoutGroup(bool display, string title)
 {
 return EditorGUILayoutUtils.DrawGUIComponentFoldoutGroup(display, title);
 }

 public static bool BeginTogglePropertyGroup(GUIContent label, bool toggle, GUIStyle style)
 {
 return EditorGUILayoutUtils.BeginTogglePropertyGroup(label, toggle, style);
 }

 public static void EndTogglePropertyGroup()
 {
 EditorGUILayoutUtils.EndTogglePropertyGroup();
 }

 public static void BeginGUIComponentIndent()
 {
 EditorGUILayoutUtils.BeginGUIComponentIndent();
 }

 public static void EndGUIComponentIndent()
 {
 EditorGUILayoutUtils.EndGUIComponentIndent();
 }

 public static void PredicateMaterialArrayBoolProperty(Material[] materials, Func<Material, bool> predicate, out bool hasMixedValue, out bool consistentValue)
 {
 hasMixedValue = false;
 bool firstOrOnlyValue = predicate(materials[0]);
 for (int i = 1; i < materials.Length; i++)
 {
 if (predicate(materials[i]) != firstOrOnlyValue)
 {
 hasMixedValue = true;
 break;
 }
 }
 consistentValue = !hasMixedValue && firstOrOnlyValue;
 }
 }
}","new_string":"using System;
using UnityEngine;

namespace ArcToon.Editor.ShaderEditor
{
 /// <summary>
 /// ShaderGUI-specific layout utilities.
 /// Shared visual styling has been moved to <see cref="EditorGUILayoutUtils"/>.
 /// This class only contains methods specific to Material/ShaderGUI editing.
 /// </summary>
 public static class ShaderGUILayout
 {
 public static void PredicateMaterialArrayBoolProperty(Material[] materials, Func<Material, bool> predicate, out bool hasMixedValue, out bool consistentValue)
 {
 hasMixedValue = false;
 bool firstOrOnlyValue = predicate(materials[0]);
 for (int i = 1; i < materials.Length; i++)
 {
 if (predicate(materials[i]) != firstOrOnlyValue)
 {
 hasMixedValue = true;
 break;
 }
 }
 consistentValue = !hasMixedValue && firstOrOnlyValue;
 }
 }
