#ifndef ARCTOON_SHADOWS_INCLUDED
#define ARCTOON_SHADOWS_INCLUDED

#include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Shadow/ShadowSamplingTent.hlsl"

#if defined(_PCF3X3)
    #define DIRECTIONAL_FILTER_SAMPLES 4
    #define SPOT_FILTER_SAMPLES 4
    #define POINT_FILTER_SAMPLES 4

    #define DIRECTIONAL_FILTER_SETUP SampleShadow_ComputeSamples_Tent_3x3
    #define SPOT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_3x3
    #define POINT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_3x3
#elif defined(_PCF5X5)
    #define DIRECTIONAL_FILTER_SAMPLES 9
    #define SPOT_FILTER_SAMPLES 9
    #define POINT_FILTER_SAMPLES 9

    #define DIRECTIONAL_FILTER_SETUP SampleShadow_ComputeSamples_Tent_5x5
    #define SPOT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_5x5
    #define POINT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_5x5
#elif defined(_PCF7X7)
    #define DIRECTIONAL_FILTER_SAMPLES 16
    #define SPOT_FILTER_SAMPLES 16
    #define POINT_FILTER_SAMPLES 16

    #define DIRECTIONAL_FILTER_SETUP SampleShadow_ComputeSamples_Tent_7x7
    #define SPOT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_7x7
    #define POINT_FILTER_SETUP SampleShadow_ComputeSamples_Tent_7x7
#endif


#include "Surface.hlsl"
#include "Common.hlsl"

TEXTURE2D_SHADOW(_DirectionalShadowAtlas);
TEXTURE2D_SHADOW(_SpotShadowAtlas);
TEXTURE2D_SHADOW(_PointShadowAtlas);
TEXTURE2D_SHADOW(_PerObjectShadowAtlas);

#define SHADOW_SAMPLER sampler_linear_clamp_compare
SAMPLER_CMP(SHADOW_SAMPLER);

CBUFFER_START(_CustomShadows)
    float4 _DirectionalShadowAtlasSize;
    float4 _SpotShadowAtlasSize;
    float4 _PointShadowAtlasSize;
    float4 _PerObjectAtlasSize;

    float4 _ShadowDistanceFade;
    int _CascadeCount;
CBUFFER_END

struct ShadowCascadeBufferData
{
    float4 cullingSphere;
    float4 data;
};

StructuredBuffer<ShadowCascadeBufferData> _ShadowCascadeData;

StructuredBuffer<float4x4> _DirectionalShadowMatrices;

struct SpotShadowBufferData
{
    // x: tile border start x
    // y: tile border start y
    // z: tile border length
    // w: shadow normal bias scale
    float4 tileData;
    float4x4 shadowMatrix;
};

StructuredBuffer<SpotShadowBufferData> _SpotShadowData;

struct PointShadowBufferData
{
    // x: tile border start x
    // y: tile border start y
    // z: tile border length
    // w: shadow normal bias scale
    float4 tileData;
    float4x4 shadowMatrix;
};

StructuredBuffer<PointShadowBufferData> _PointShadowData;

struct PerObjectShadowBufferData
{
    float4 normalBias;
    float4x4 shadowMatrix;
};

StructuredBuffer<PerObjectShadowBufferData> _PerObjectShadowData;

struct ShadowMask
{
    bool alwaysMode;
    bool distanceMode;
    float4 shadows;
};

struct CascadeShadowData
{
    int offset;
    float softBlend;
    float rangeFade;
};

CascadeShadowData GetCascadeShadowData(Surface surface)
{
    CascadeShadowData cascade;
    int i;
    cascade.rangeFade = 1.0;
    cascade.softBlend = 1.0;
    for (i = 0; i < _CascadeCount; i++)
    {
        ShadowCascadeBufferData bufferData = _ShadowCascadeData[i];
        float distanceSqr = DistanceSquared(surface.positionWS, bufferData.cullingSphere.xyz);
        if (distanceSqr < bufferData.cullingSphere.w)
        {
            float fade = FadedStrength(distanceSqr, bufferData.data.x, _ShadowDistanceFade.z);
            if (i == _CascadeCount - 1)
            {
                cascade.rangeFade *= fade;
            }
            else
            {
                cascade.softBlend *= fade;
            }
            break;
        }
    }
    // stop sampling if directional & end up beyond the last cascade
    if (i == _CascadeCount)
    {
        cascade.rangeFade = 0.0;
    }
    #if !defined(_CASCADE_BLEND_SOFT)
    else if (cascade.softBlend < surface.dither)
    {
        i += 1;
    }
    #endif

    cascade.offset = i;
    return cascade;
}

float GetBakedShadow(ShadowMask mask, int channel, float strength)
{
    if (strength <= 0) return 1.0;
    float shadow = 1.0;
    if (mask.alwaysMode || mask.distanceMode)
    {
        if (channel >= 0)
        {
            shadow = mask.shadows[channel];
        }
    }
    return lerp(1.0, shadow, strength);
}

float MixBakedAndRealtimeShadow(float bakedShadow, float realtimeShadow, float fade)
{
    return lerp(bakedShadow, realtimeShadow, fade);
}

// TODO: bounds?
float SampleDirectionalShadowAtlas(float3 positionSTS)
{
    return SAMPLE_TEXTURE2D_SHADOW(
        _DirectionalShadowAtlas, SHADOW_SAMPLER, positionSTS
    );
}

float FilterDirectionalShadow(float3 positionSTS)
{
    #if defined(DIRECTIONAL_FILTER_SETUP)
    float weights[DIRECTIONAL_FILTER_SAMPLES];
    float2 positions[DIRECTIONAL_FILTER_SAMPLES];
    float4 size = _DirectionalShadowAtlasSize;
    DIRECTIONAL_FILTER_SETUP(size, positionSTS.xy, weights, positions);
    float shadow = 0;
    for (int i = 0; i < DIRECTIONAL_FILTER_SAMPLES; i++)
    {
        shadow += weights[i] * SampleDirectionalShadowAtlas(
            float3(positions[i].xy, positionSTS.z)
        );
    }
    return shadow;
    #else
    return SampleDirectionalShadowAtlas(positionSTS);
    #endif
}

float SamplePerObjectShadowAtlas(float3 positionSTS)
{
    return SAMPLE_TEXTURE2D_SHADOW(
        _PerObjectShadowAtlas, SHADOW_SAMPLER, positionSTS
    );
}

float FilterPerObjectShadow(float3 positionSTS)
{
    #if defined(DIRECTIONAL_FILTER_SETUP)
    float weights[DIRECTIONAL_FILTER_SAMPLES];
    float2 positions[DIRECTIONAL_FILTER_SAMPLES];
    float4 size = _PerObjectAtlasSize;
    DIRECTIONAL_FILTER_SETUP(size, positionSTS.xy, weights, positions);
    float shadow = 0;
    for (int i = 0; i < DIRECTIONAL_FILTER_SAMPLES; i++)
    {
        shadow += weights[i] * SamplePerObjectShadowAtlas(
            float3(positions[i].xy, positionSTS.z)
        );
    }
    return shadow;
    #else
    return SamplePerObjectShadowAtlas(positionSTS);
    #endif
}

float SampleSpotShadowAtlas(float3 positionSTS, float3 bounds)
{
    positionSTS.xy = clamp(positionSTS.xy, bounds.xy, bounds.xy + bounds.z);
    return SAMPLE_TEXTURE2D_SHADOW(
        _SpotShadowAtlas, SHADOW_SAMPLER, positionSTS
    );
}

float FilterSpotShadow(float3 positionSTS, float3 bounds)
{
    #if defined(SPOT_FILTER_SETUP)
    real weights[SPOT_FILTER_SAMPLES];
    real2 positions[SPOT_FILTER_SAMPLES];
    float4 size = _SpotShadowAtlasSize;
    SPOT_FILTER_SETUP(size, positionSTS.xy, weights, positions);
    float shadow = 0;
    for (int i = 0; i < SPOT_FILTER_SAMPLES; i++)
    {
        shadow += weights[i] * SampleSpotShadowAtlas(
            float3(positions[i].xy, positionSTS.z), bounds
        );
    }
    return shadow;
    #else
    return SampleSpotShadowAtlas(positionSTS, bounds);
    #endif
}

float SamplePointShadowAtlas(float3 positionSTS, float3 bounds)
{
    positionSTS.xy = clamp(positionSTS.xy, bounds.xy, bounds.xy + bounds.z);
    return SAMPLE_TEXTURE2D_SHADOW(
        _PointShadowAtlas, SHADOW_SAMPLER, positionSTS
    );
}

float FilterPointShadow(float3 positionSTS, float3 bounds)
{
    #if defined(POINT_FILTER_SETUP)
    real weights[POINT_FILTER_SAMPLES];
    real2 positions[POINT_FILTER_SAMPLES];
    float4 size = _PointShadowAtlasSize;
    POINT_FILTER_SETUP(size, positionSTS.xy, weights, positions);
    float shadow = 0;
    for (int i = 0; i < POINT_FILTER_SAMPLES; i++)
    {
        shadow += weights[i] * SamplePointShadowAtlas(
            float3(positions[i].xy, positionSTS.z), bounds
        );
    }
    return shadow;
    #else
    return SamplePointShadowAtlas(positionSTS, bounds);
    #endif
}

#endif

using System.Runtime.InteropServices;
using ArcToon.Runtime.Buffers;
using ArcToon.Runtime.Data;
using ArcToon.Runtime.Jobs;
using ArcToon.Runtime.Passes.Lighting;
using ArcToon.Runtime.Settings;
using ArcToon.Runtime.Utils;
using Unity.Collections;
using UnityEngine;
using UnityEngine.Rendering.RenderGraphModule;
using UnityEngine.Rendering;
using Unity.Jobs;
using Unity.Mathematics;
using static Unity.Mathematics.math;

namespace ArcToon.Runtime.Passes
{
    public class LightingPass : RenderGraphPassBase
    {
        public override ProfilingSampler Sampler => new("Lighting");

        private ShadowMapRenderer shadowMapRenderer = new();
        private PerLightDataCollector perLightDataCollector = new();

        private RenderGraph renderGraph;

        #region DirectionalLight
        int directionalLightCount;

        private static readonly DirectionalLightBufferData[] DirectionalLightData =
            new DirectionalLightBufferData[RenderPipelineInfo.MaxDirectionalLightCount];
        #endregion

        #region SpotLight
        int spotLightCount;

        private static readonly SpotLightBufferData[] SpotLightData = 
            new SpotLightBufferData[RenderPipelineInfo.MaxSpotLightCount];
        #endregion

        #region PointLight
        int pointLightCount;

        private static readonly PointLightBufferData[] PointLightData = 
            new PointLightBufferData[RenderPipelineInfo.MaxPointLightCount];
        #endregion

        #region PerObjectShadow
        int perObjectCasterCount;

        private static readonly PerObjectCasterBufferData[] PerObjectCasterData =
            new PerObjectCasterBufferData[RenderPipelineInfo.MaxPerObjectCasterCount];
        #endregion

        #region TileForward+
        JobHandle forwardPlusJobHandle;

        NativeArray<float4> spotLightBounds;
        NativeArray<float4> pointLightBounds;

        NativeArray<int> forwardPlusTileData;

        private int maxLightCountPerTile;
        private int tileDataSize;

        Vector2 screenUVToTileCoordinates;

        Vector2Int tileCount;
        int TileCount => tileCount.x * tileCount.y;
        #endregion

        public override void Initialize(RenderGraphResourceHandle resourceHandle, CameraRenderer renderer)
        {
            base.Initialize(resourceHandle, renderer);

            maxLightCountPerTile = renderer.ForwardPlusSettings.maxLightsPerTile;
            tileDataSize = maxLightCountPerTile + 2;

            spotLightBounds = new NativeArray<float4>(RenderPipelineInfo.MaxSpotLightCount,
                Allocator.TempJob,
                NativeArrayOptions.UninitializedMemory);
            pointLightBounds = new NativeArray<float4>(RenderPipelineInfo.MaxPointLightCount,
                Allocator.TempJob,
                NativeArrayOptions.UninitializedMemory);

            float tileScreenPixelSize = renderer.ForwardPlusSettings.tileSize <= 0 ? 64f : (float)renderer.ForwardPlusSettings.tileSize;
            screenUVToTileCoordinates.x = renderer.AttachmentSize.x / tileScreenPixelSize;
            screenUVToTileCoordinates.y = renderer.AttachmentSize.y / tileScreenPixelSize;
            tileCount.x = Mathf.CeilToInt(screenUVToTileCoordinates.x);
            tileCount.y = Mathf.CeilToInt(screenUVToTileCoordinates.y);

            perLightDataCollector.Setup(renderer.CullingResults, renderer.ShadowSettings);
            CollectPerLightData();

            shadowMapRenderer.Initialize(renderer.CullingResults, Camera, renderer.ShadowSettings, perLightDataCollector,
                renderer.PerObjectShadowCasterManager);
        }

        public override bool AllowCulling() => false;

        public override void Render(CommandBuffer commandBuffer, ScriptableRenderContext context)
        {
            commandBuffer.SetGlobalInt(InternalShader.PropertyID.DirectionalLightCount, directionalLightCount);
            commandBuffer.SetBufferData(resourceHandle.lightDataDirectional, DirectionalLightData,
                0, 0, directionalLightCount);
            commandBuffer.SetGlobalBuffer(InternalShader.PropertyID.DirectionalLightData, resourceHandle.lightDataDirectional);

            commandBuffer.SetGlobalInt(InternalShader.PropertyID.PerObjectShadowCasterCount, perObjectCasterCount);
            commandBuffer.SetBufferData(resourceHandle.perObjectShadowCasterData, PerObjectCasterData, 
                0, 0, perObjectCasterCount);
            commandBuffer.SetGlobalBuffer(InternalShader.PropertyID.PerObjectShadowCasterData, resourceHandle.perObjectShadowCasterData);

            commandBuffer.SetGlobalInt(InternalShader.PropertyID.SpotLightCount, spotLightCount);
            commandBuffer.SetBufferData(resourceHandle.lightDataSpot, SpotLightData,
                0, 0, spotLightCount);
            commandBuffer.SetGlobalBuffer(InternalShader.PropertyID.SpotLightData, resourceHandle.lightDataSpot);

            commandBuffer.SetGlobalInt(InternalShader.PropertyID.PointLightCount, pointLightCount);
            commandBuffer.SetBufferData(resourceHandle.lightDataPoint, PointLightData,
                0, 0, pointLightCount);
            commandBuffer.SetGlobalBuffer(InternalShader.PropertyID.PointLightData, resourceHandle.lightDataPoint);

            shadowMapRenderer.RenderShadowMap(commandBuffer, context);

            // block waiting for job result
            forwardPlusJobHandle.Complete();
            commandBuffer.SetBufferData(resourceHandle.forwardPlusTileBuffer, forwardPlusTileData,
                0, 0, forwardPlusTileData.Length);
            commandBuffer.SetGlobalBuffer(InternalShader.PropertyID.ForwardPlusTileData, resourceHandle.forwardPlusTileBuffer);
            commandBuffer.SetGlobalVector(InternalShader.PropertyID.ForwardPlusTileSettings,
                new Vector4(screenUVToTileCoordinates.x, screenUVToTileCoordinates.y,
                    asfloat(tileCount.x),
                    asfloat(tileDataSize)
                )
            );

            spotLightBounds.Dispose();
            pointLightBounds.Dispose();
            forwardPlusTileData.Dispose();
        }

        public override void AcquireResource(RenderGraph renderGraph)
        {
            this.renderGraph = renderGraph;
            resourceHandle.lightDataSpot = renderGraph.CreateBuffer(new BufferDesc(RenderPipelineInfo.MaxSpotLightCount, SpotLightBufferData.stride)
            {
                name = "Spot Light Data",
                target = GraphicsBuffer.Target.Structured
            });
            resourceHandle.lightDataPoint = renderGraph.CreateBuffer(new BufferDesc(RenderPipelineInfo.MaxPointLightCount, PointLightBufferData.stride)
            {
                name = "Point Light Data",
                target = GraphicsBuffer.Target.Structured
            });
            resourceHandle.lightDataDirectional = renderGraph.CreateBuffer(new BufferDesc(RenderPipelineInfo.MaxDirectionalLightCount, DirectionalLightBufferData.stride)
            {
                name = "Directional Light Data",
                target = GraphicsBuffer.Target.Structured
            });
            resourceHandle.perObjectShadowCasterData = renderGraph.CreateBuffer(new BufferDesc(RenderPipelineInfo.MaxPerObjectCasterCount, PerObjectCasterBufferData.stride)
            {
                name = "Per Object Shadow Caster Data",
                target = GraphicsBuffer.Target.Structured
            });
            resourceHandle.forwardPlusTileBuffer = renderGraph.CreateBuffer(new BufferDesc(TileCount * tileDataSize, 4)
            {
                name = "Forward+ Tiles",
                target = GraphicsBuffer.Target.Structured
            });
        }

        public override void DeclareResourceUsage(RenderGraphBuilder builder)
        {
            builder.WriteBuffer(resourceHandle.lightDataSpot);
            builder.WriteBuffer(resourceHandle.lightDataPoint);
            builder.WriteBuffer(resourceHandle.lightDataDirectional);
            builder.WriteBuffer(resourceHandle.perObjectShadowCasterData);
            builder.WriteBuffer(resourceHandle.forwardPlusTileBuffer);

            // TODO: reorganize
            resourceHandle.shadowMapHandle = shadowMapRenderer.Record(renderGraph, builder, renderer.Context);
        }

        private void CollectPerLightData()
        {
            NativeArray<VisibleLight> visibleLights = renderer.CullingResults.visibleLights;

            directionalLightCount = 0;
            spotLightCount = 0;
            pointLightCount = 0;
            for (int i = 0; i < visibleLights.Length; i++)
            {
                Light light = visibleLights[i].light;
                switch (visibleLights[i].lightType)
                {
                    case LightType.Directional when directionalLightCount < RenderPipelineInfo.MaxDirectionalLightCount:
                        DirectionalLightData[directionalLightCount++] =
                            DirectionalLightBufferData.GenerateStructuredData(visibleLights[i], light,
                                perLightDataCollector.ReservePerLightShadowDataDirectional(light, i));
                        break;
                    case LightType.Spot when spotLightCount < RenderPipelineInfo.MaxSpotLightCount:
                        SetupForwardPlusSpot(spotLightCount, visibleLights[i]);
                        SpotLightData[spotLightCount++] =
                            SpotLightBufferData.GenerateStructuredData(visibleLights[i], light,
                                perLightDataCollector.ReservePerLightShadowDataSpot(light, i));
                        break;
                    case LightType.Point when pointLightCount < RenderPipelineInfo.MaxPointLightCount:
                        SetupForwardPlusPoint(pointLightCount, visibleLights[i]);
                        PointLightData[pointLightCount++] =
                            PointLightBufferData.GenerateStructuredData(visibleLights[i], light,
                                perLightDataCollector.ReservePerLightShadowDataPoint(light, i));
                        break;
                }
            }

            var visiblePerObjectShadowCasters = renderer.PerObjectShadowCasterManager.visibleCasters;
            perObjectCasterCount = 0;
            for (int i = 0; i < visiblePerObjectShadowCasters.Count; i++)
            {
                var caster = visiblePerObjectShadowCasters[i];
                if (perObjectCasterCount < RenderPipelineInfo.MaxPerObjectCasterCount)
                {
                    PerObjectCasterData[perObjectCasterCount++] =
                        PerObjectCasterBufferData.GenerateStructuredData(
                            perLightDataCollector.ReservePerObjectShadowCasterData(caster, i));
                }
            }

            forwardPlusTileData = new NativeArray<int>(TileCount * tileDataSize, Allocator.TempJob);
            forwardPlusJobHandle = new ForwardPlusTileBoundJob()
            {
                tileData = forwardPlusTileData,
                spotLightBounds = spotLightBounds,
                pointLightBounds = pointLightBounds,
                spotLightCount = spotLightCount,
                pointLightCount = pointLightCount,
                tileScreenUVSize = float2(
                    1f / screenUVToTileCoordinates.x,
                    1f / screenUVToTileCoordinates.y),
                maxLightCountPerTile = maxLightCountPerTile,
                tilesPerRow = tileCount.x,
                tileDataSize = tileDataSize
            }.ScheduleParallel(TileCount, tileCount.x, default);
        }

        private void SetupForwardPlusSpot(int spotlightIndex, in VisibleLight visibleLight)
        {
            Rect r = visibleLight.screenRect;
            spotLightBounds[spotlightIndex] = float4(r.xMin, r.yMin, r.xMax, r.yMax);
        }

        private void SetupForwardPlusPoint(int pointlightIndex, in VisibleLight visibleLight)
        {
            Rect r = visibleLight.screenRect;
            pointLightBounds[pointlightIndex] = float4(r.xMin, r.yMin, r.xMax, r.yMax);
        }
    }
}

#ifndef ARCTOON_DIRECTIONAL_LIGHT_INCLUDED
#define ARCTOON_DIRECTIONAL_LIGHT_INCLUDED

#include "../Shadow.hlsl"
#include "../GI.hlsl"
#include "LightType.hlsl"

CBUFFER_START(_CustomDirectionalLight)
    int _DirectionalLightCount;
    int _PerObjectShadowCasterCount;
CBUFFER_END

struct DirectionalLightBufferData
{
    float4 color;
    float4 direction;
    // x: shadow strength
    // y: shadowed directional light index
    // z: shadow slope scale bias
    // w: shadow mask channel
    float4 shadowData;
};

StructuredBuffer<DirectionalLightBufferData> _DirectionalLightData;

struct DirectionalLightShadowData
{
    float shadowStrength;
    int tileIndex;
    int shadowedLightIndex;
    float normalBiasScale;
    int shadowMaskChannel;
};

struct PerObjectCasterBufferData
{
    float4 perObjectData;

    bool CheckCasterID(float casterID)
    {
        return abs(perObjectData.y - casterID) <= 0.01;
    }
};

StructuredBuffer<PerObjectCasterBufferData> _PerObjectShadowCasterData;

DirectionalLightShadowData DecodeDirectionalLightShadowData(DirectionalLightBufferData bufferData,
                                                            CascadeShadowData cascadeShadowData)
{
    DirectionalLightShadowData data;
    data.shadowStrength = bufferData.shadowData.x;
    data.shadowedLightIndex = bufferData.shadowData.y;
    data.tileIndex = bufferData.shadowData.y * _CascadeCount + cascadeShadowData.offset;
    data.normalBiasScale = bufferData.shadowData.z;
    data.shadowMaskChannel = bufferData.shadowData.w;
    return data;
}

float GetDirectionalRealtimeShadow(DirectionalLightShadowData directional, CascadeShadowData cascade,
                                   Surface surface)
{
    if (directional.shadowStrength <= 0) return 1.0;
    if (surface.perObjectCasterID > 0)
    {
        for (int i = 0; i < _PerObjectShadowCasterCount; i++)
        {
            PerObjectCasterBufferData bufferData = _PerObjectShadowCasterData[i];
            if (bufferData.CheckCasterID(surface.perObjectCasterID))
            {
                int tileIndex = bufferData.perObjectData.z + directional.shadowedLightIndex;
                PerObjectShadowBufferData shadowData = _PerObjectShadowData[tileIndex];
                float3 normalBias = surface.interpolatedNormalWS * shadowData.normalBias.x * directional.normalBiasScale;
                float3 positionSTS = mul(shadowData.shadowMatrix,
                                         float4(surface.positionWS + normalBias, 1.0)).xyz;
                float shadow = FilterPerObjectShadow(positionSTS);
                shadow = lerp(1.0, shadow, directional.shadowStrength);
                return shadow;
            }
        }
    }
    float3 normalBias = surface.interpolatedNormalWS * _ShadowCascadeData[cascade.offset].data.y * directional.normalBiasScale;
    float3 positionSTS = mul(_DirectionalShadowMatrices[directional.tileIndex],
                             float4(surface.positionWS + normalBias, 1.0)).xyz;
    float shadow = FilterDirectionalShadow(positionSTS);
    #if defined(_CASCADE_BLEND_SOFT)
    // cascade shadow blend
    normalBias = surface.normalWS * _ShadowCascadeData[cascade.offset].data.y * directional.normalBiasScale;
    positionSTS = mul(_DirectionalShadowMatrices[directional.tileIndex + 1],
                      float4(surface.positionWS + normalBias, 1.0)).xyz;
    shadow = lerp(FilterDirectionalShadow(positionSTS), shadow, cascade.softBlend);
    #endif
    shadow = lerp(1.0, shadow, directional.shadowStrength);
    return shadow;
}

float GetDirectionalShadowAttenuation(DirectionalLightShadowData directional, CascadeShadowData cascade,
                                      Surface surface, GI gi)
{
    #if !defined(_RECEIVE_SHADOWS)
    return 1.0;
    #endif
    float realtimeShadow = GetDirectionalRealtimeShadow(directional, cascade, surface);
    float attenuation;
    // farther than max distance but still inside the last culling sphere
    float fade = FadedStrength(surface.linearDepth, _ShadowDistanceFade.x, _ShadowDistanceFade.y) * cascade.rangeFade;
    if (gi.shadowMask.alwaysMode)
    {
        // TODO:
        float bakedShadow = GetBakedShadow(gi.shadowMask, directional.shadowMaskChannel,
                                           abs(directional.shadowStrength));
        attenuation = MixBakedAndRealtimeShadow(bakedShadow, realtimeShadow, fade);
    }
    else if (gi.shadowMask.distanceMode)
    {
        float bakedShadow = GetBakedShadow(gi.shadowMask, directional.shadowMaskChannel,
                                           abs(directional.shadowStrength));
        attenuation = MixBakedAndRealtimeShadow(bakedShadow, realtimeShadow, fade);
    }
    else
    {
        attenuation = lerp(1.0, realtimeShadow, fade);
    }
    return attenuation;
}

Light GetDirectionalLight(int lightIndex, Surface surface, CascadeShadowData cascade, GI gi)
{
    DirectionalLightBufferData bufferData = _DirectionalLightData[lightIndex];
    Light light;
    light.isMainLight = lightIndex == 0;
    light.color = bufferData.color.rgb;
    light.directionWS = bufferData.direction.xyz;
    light.renderingLayerMask = bufferData.direction.w;
    DirectionalLightShadowData dirShadowData = DecodeDirectionalLightShadowData(bufferData, cascade);
    light.shadowAttenuation = GetDirectionalShadowAttenuation(dirShadowData, cascade, surface, gi);
    light.distanceAttenuation = 1.0;
    return light;
}

