Light GetDirectionalLight(int lightIndex, Surface surface, CascadeShadowData cascade, GI gi)
{
    DirectionalLightBufferData bufferData = _DirectionalLightData[lightIndex];
    Light light;
    light.isMainLight = lightIndex == 0;
