 }

 CullMode CullMode
 {
 set => SetProperty("_Cull", (float)value);
 }

 RenderQueue RenderQueue
 {
 set
 {
 foreach (var o in materials)
 {
 var material = (Material)o;
 material.renderQueue = (int)value;
 }
 }
 }

