#define ARCTOON_POISSON_DISK_INCLUDED

#define POISSON_SAMPLE_COUNT 16

// 定义此宏以启用运行时 Vogel Disk 采样（代替预计算数组）
// 优点：每像素随机旋转，消除规律性伪影
// 注释此宏则回退到预计算 Poisson Disk 数组
// #define POISSON_DISK_RUNTIME

#if defined(POISSON_DISK_RUNTIME)

// =============================================
// 运行时 Vogel Disk 采样
// =============================================

// 黄金角 (Golden Angle) ≈ 2.399963 rad
#define GOLDEN_ANGLE 2.3999632297286533

// 基于屏幕空间坐标的伪随机函数，用于生成每像素的随机旋转角度
float InterleavedGradientNoise(float2 screenPos)
{
 float3 magic = float3(0.06711056, 0.00583715, 52.9829189);
 return frac(magic.z * frac(dot(screenPos, magic.xy)));
}

// 运行时生成第 i 个 Vogel Disk 采样偏移
// sampleIndex: 当前采样索引 [0, POISSON_SAMPLE_COUNT)
// sampleCount: 总采样数
// rotation: 每像素随机旋转角度（弧度）
float2 VogelDiskSample(int sampleIndex, int sampleCount, float rotation)
{
 float goldenAngle = GOLDEN_ANGLE;
 float r = sqrt((float)sampleIndex + 0.5) / sqrt((float)sampleCount);
 float theta = (float)sampleIndex * goldenAngle + rotation;

 return float2(r * cos(theta), r * sin(theta));
}

#else

// =============================================
// 预计算 Poisson Disk 采样数组
// =============================================

static const float2 poissonDisk[POISSON_SAMPLE_COUNT] =
{
