{
    float texelSize = _DirectionalShadowAtlasSize.y;
    float shadow = 0;
    InitPoissonDisk(positionSTS.xy * _DirectionalShadowAtlasSize.x);
    for (int i = 0; i < POISSON_SAMPLE_COUNT; i++)
